const a=e=>{switch(e){case"auth/email-already-in-use":return"This email is already registered. Try logging in instead.";case"auth/invalid-email":return"The email address is not valid.";case"auth/operation-not-allowed":return"This login method is currently disabled.";case"auth/weak-password":return"The password is too weak. Use at least 8 characters with numbers and symbols.";case"auth/user-disabled":return"This account has been disabled. Contact support for assistance.";case"auth/user-not-found":return"No account found with this email.";case"auth/wrong-password":return"Incorrect password. Please try again.";case"auth/too-many-requests":return"Too many failed attempts. Please try again later.";case"auth/network-request-failed":return"Network error. Please check your internet connection.";case"auth/credential-already-in-use":return"This account is already linked to another user.";case"auth/requires-recent-login":return"For security, please log in again before performing this action.";case"auth/invalid-verification-code":return"The SMS code is incorrect. Please try again.";case"auth/invalid-verification-id":return"The verification session has expired. Please request a new code.";case"auth/captcha-check-failed":return"reCAPTCHA verification failed. Please try again.";default:return"An unexpected error occurred. Please try again."}};export{a as g};
